import java.util.*;

class Solution {
    private static class Node {
        Node[] child = new Node[2];
    }

    public int[] cappedXor(int[] nums, int[][] queries) {
        int[] a = nums.clone();
        Arrays.sort(a);
        int q = queries.length;
        Integer[] order = new Integer[q];
        for (int i = 0; i < q; i++) order[i] = i;
        Arrays.sort(order, (x, y) -> Integer.compare(queries[x][1], queries[y][1])); // by cap

        Node root = new Node();
        int[] ans = new int[q];
        int k = 0;
        for (int qi : order) {
            int x = queries[qi][0], cap = queries[qi][1];
            while (k < a.length && a[k] <= cap) {   // add every number allowed by this cap
                Node cur = root;
                for (int b = 29; b >= 0; b--) {
                    int bit = (a[k] >> b) & 1;
                    if (cur.child[bit] == null) cur.child[bit] = new Node();
                    cur = cur.child[bit];
                }
                k++;
            }
            if (k == 0) { ans[qi] = -1; continue; } // nothing is small enough
            Node cur = root;
            int val = 0;
            for (int b = 29; b >= 0; b--) {         // greedy opposite-bit walk
                int bit = (x >> b) & 1;
                if (cur.child[1 - bit] != null) {
                    val |= 1 << b;
                    cur = cur.child[1 - bit];
                } else {
                    cur = cur.child[bit];
                }
            }
            ans[qi] = val;
        }
        return ans;
    }
}

